# Lanternhold: Ember Ring team battles, server part. Paste into AWS CloudShell (us-east-1). Needs John's go.
# Updates only the code of Lambda lanternhold-arena (from infra/ring/index.js). No new routes, tables or roles:
# team battles ride on the existing routes (PUT /arena with tl, POST /arena/kit with cid, POST /arena/fight with team: 1).
# Old game builds keep working: duels, Ring skills and the Ringwarden kit are unchanged.
# Backs up the current code to ~/lhbak first. Safe to run twice.
set -e
F=lanternhold-arena; T=$(date -u +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhteam && cd ~/lhteam
curl -s -o ~/lhbak/$F-$T.zip "$(aws lambda get-function --function-name $F --query Code.Location --output text)"
echo "backup: ~/lhbak/$F-$T.zip ($(stat -c %s ~/lhbak/$F-$T.zip) bytes)"
echo  | base64 -d > index.js
[ "$(md5sum index.js | cut -c1-32)" = "ff7ec444a85860cae7eebbc3ae0183e5" ] || { echo "The code did not paste cleanly. Nothing changed."; exit 1; }
rm -f ring.zip && zip -qj ring.zip index.js
aws lambda update-function-code --function-name $F --zip-file fileb://ring.zip >/dev/null
aws lambda wait function-updated --function-name $F
# smoke test: without sign-in the Ring must still say 401
curl -s -o /dev/null -w "GET /arena without sign-in: %{http_code} (401 is right)\n" https://nyu3u8gc73.execute-api.us-east-1.amazonaws.com/arena
echo "done. Undo: aws lambda update-function-code --function-name $F --zip-file fileb://$HOME/lhbak/$F-$T.zip"
